Object.assign(window.deepArticles, {
  "japanese-imperial-economic-system": japaneseEconomicArticle({
    title:"Greater East Asia Co-Prosperity Economic System",category:"Economic systems",eyebrow:"Daitōa Kyōei Keizai Taisei · from 1948",infoboxKicker:"Japanese-led developmental order",
    flag:{src:"assets/diagrams/japanese-imperial-economic-system.svg",alt:"Diagram of Japan's imperial economic system",caption:"Tokyo sets the strategic envelope while banks, corporate houses, trading companies, and policy corporations implement it"},
    lead:"The Greater East Asia Co-Prosperity Economic System is the bank-centered and maritime developmental order through which Japan directs the economy of its empire without operating every mine, ship, bank, or factory. Imperial plans govern access to credit, shipping, foreign exchange, concessions, technology, and protection; formally private corporations and sovereign governments conduct much of the daily work.",
    canon:"The system's 1948 foundation, principal institutions, corporate method, layered money, industrial hierarchy, social bargain, and long-term soft-budget weakness are established. Exact Japanese statutory titles, corporate market shares, plan appropriations, and later restructuring sequence remain open.",
    sections:[
      {id:"origins",title:"Victory without occupation",html:"<p>Japan reaches 1947 fiscally strained but physically intact. The home islands have not been invaded, the industrial combines have not been dissolved, and maritime access to rice, petroleum, rubber, tin, bauxite, and coal survives. Inflation, debt, rationing, black markets, and suppressed civilian demand require stabilization rather than reconstruction from national ruin.</p><p>The absence of an occupation permits wartime control associations, designated banks, professional management, and state-directed finance to become permanent peacetime institutions.</p>"},
      {id:"constitution",title:"A relational rather than warehouse empire",html:"<p>Germany centralizes many imperial resources through administrative pools. Japan normally assigns a bank, trading company, corporate group, shipping line, and host government to finance, move, refine, insure, and sell them.</p><p>The result is less visibly centralized but not necessarily less controlled. Tokyo decides which projects receive cheap credit, ships, exchange licenses, market entry, military protection, and permission to fail.</p>"},
      {id:"institutions",title:"Central institutions",html:"<p>The <a href='greater-east-asia-economic-board.html'>Greater East Asia Economic Board</a> sets priorities. The <a href='japanese-ministry-of-finance.html'>Ministry of Finance</a> governs exchange, banking, bonds, and capital movement; the <a href='bank-of-japan.html'>Bank of Japan</a> manages the domestic yen and designated-bank liquidity; the <a href='imperial-development-bank.html'>Imperial Development Bank</a> supplies patient development finance.</p><p>Sector ministries, the Imperial Defense Council, associated governments, and corporate representatives convert broad plans into legal concessions and operating projects.</p>"},
      {id:"corporations",title:"Corporate implementation",html:"<p><a href='japanese-imperial-corporate-houses.html'>Imperial corporate houses</a> combine banks, insurers, trading companies, shipping, industry, research, and overseas subsidiaries. <a href='sogo-shosha.html'><em>Sōgō shōsha</em></a> arrange contracts and movement; <a href='japanese-national-policy-corporations.html'>national-policy corporations</a> join public guarantees to private management.</p><p>The state cultivates several obedient giants and selected rising enterprises rather than either one monopoly or unrestricted antitrust competition.</p>"},
      {id:"money",title:"Layered money and controlled convertibility",html:"<p>The <a href='japanese-yen-area.html'>yen area</a> includes the domestic fiat yen, inner-imperial notes, pegged development currencies, more autonomous baht and peso systems, the noncash <a href='greater-east-asia-clearing-yen.html'>Clearing Yen</a>, and the separate external <a href='gold-yen.html'>Gold Yen</a>.</p><p>Multiple currencies preserve national symbols. Japanese institutions remain indispensable because they determine reserve access, approved redemption, credit, and the exchange value of large transactions.</p>"},
      {id:"ladder",title:"The imperial production ladder",html:"<p>Japan retains advanced design, finance, machine tools, naval systems, electronics, computing, nuclear engineering, robotics, and high-end goods. Chōsen and Manchukuo carry major industrial work. China remains concentrated in ordinary industry, while Southeast Asia supplies resources, refining, ports, and a growing manufacturing base.</p><p>Industrialization follows a hierarchy in which associated societies gain productive capacity but remain dependent upon Japanese control of strategic technology and capital.</p>"},
      {id:"society",title:"Firm-centered social order",html:"<p>Favored core employees receive long employment, seniority wages, housing, medical care, schools, apprenticeships, pensions, recreation, and subsidized shops. Firms expect long hours, transfers across the empire, political conformity, and company-centered representation in return.</p><p>Colonial and associated workers occupy lower tiers. Chronic demand for technicians gradually opens skilled careers to Koreans, Taiwanese, Manchurians, and others while senior authority remains disproportionately Japanese.</p>"},
      {id:"contradictions",title:"Success and accumulated weakness",html:"<p>Protected markets, secure resources, disciplined finance, nuclear power, technical education, and automation make Japan one of the world's leading industrial systems. They also preserve politically connected capacity and colonial loans that ordinary competition would close.</p><p>By the 1970s <a href='protected-national-enterprises-japan.html'>protected national enterprises</a>, maritime vulnerability, corporate arrogance, and demands for local ascent reveal the cost of a system that can direct growth more easily than it can recognize failure.</p>"}
    ],
    related:[{href:"japan.html",kicker:"Leading state",label:"Empire of Japan"},{href:"geacps.html",kicker:"International order",label:"Greater East Asia Co-Prosperity Sphere"},{href:"greater-east-asia-economic-board.html",kicker:"Planning authority",label:"Greater East Asia Economic Board"},{href:"japanese-yen-area.html",kicker:"Monetary architecture",label:"Japanese Imperial Yen Area"},{href:"political-economy.html",kicker:"Comparative portal",label:"Political Economy by Bloc"}],
    facts:[["Established","1948 settlement"],["Common Japanese title","Daitōa Kyōei Keizai Taisei"],["Planning authority","Greater East Asia Economic Board"],["Principal method","Directed credit and corporate implementation"],["Development lender","Imperial Development Bank"],["Corporate core","Zaibatsu and sōgō shōsha"],["Common circulating Sphere currency","None"],["Long-term weakness","Protected capacity and politically directed bad loans"]]
  }),

  "imperial-financial-rectification": japaneseEconomicArticle({
    title:"Imperial Financial Rectification",category:"Economic history",eyebrow:"Teikoku Kin’yū Seiri · New Yen Settlement · 1948",infoboxKicker:"Japanese postwar monetary settlement",
    flag:{src:"assets/diagrams/japanese-development-plan-sequence.svg",alt:"Timeline of Japanese stabilization and development plans",caption:"The 1948 settlement is the monetary foundation of the later reconstruction and prosperity plans"},
    lead:"The Imperial Financial Rectification of 1948, publicly called the New Yen Settlement, was Japan's conversion from a victorious war economy to a stable developmental empire. It protected current wages and modest household savings, imposed heavier conversion on large wartime balances, exchanged government claims for long reconstruction paper, and created the financial foundation of the layered yen area.",
    canon:"The year, dual names, disinflationary purpose, protection of small balances, conversion of large holdings and bonds, reconstruction account, and reorganization of imperial currencies are established. Exact conversion ratios, eligibility thresholds, bond coupons, and month of promulgation remain open.",
    sections:[
      {id:"conditions",title:"The monetary overhang of victory",html:"<p>Years of bond finance, controlled prices, rationing, military procurement, and suppressed consumption leave too much money and too many paper claims chasing too few civilian goods. Black-market prices reveal inflation concealed by official schedules.</p><p>Unlike defeated historical Japan, the country retains factories, ports, ships, imperial resources, and political continuity. The Cabinet can therefore combine monetary restraint with a genuine restoration of supply.</p>"},
      {id:"purpose",title:"Disinflation rather than permanent deflation",html:"<p>Tokyo rejects indefinite falling prices after the destructive interwar experience. It accepts stringent credit and possibly a brief mild deflation to restore confidence, while aiming at stable prices, reopened trade, and investment rather than liquidation for its own sake.</p><p>The settlement must destroy part of the wartime claim without destroying the banks and corporate houses needed to finance peace.</p>"},
      {id:"households",title:"Current income and small balances",html:"<p>Current wages, pensions, rents, and ordinary retail prices convert broadly at par. Small deposits—especially those of soldiers' families, widows, farmers, and salaried households—receive preferential protection.</p><p>This political choice separates national service and ordinary thrift from speculative gains. It prevents stabilization from appearing as a second defeat imposed upon households after victory.</p>"},
      {id:"large",title:"Large balances and wartime claims",html:"<p>Large cash holdings and speculative balances convert on less favorable terms or remain blocked. Official rhetoric presents the loss as a levy upon profits accumulated during national sacrifice.</p><p>Military contracts are audited and corporations receive viable operating accounts, but they cannot cash every wartime promise. The state preserves productive firms while extinguishing claims that would overwhelm the new consumer economy.</p>"},
      {id:"bonds",title:"Imperial Reconstruction Bonds",html:"<p>Government bonds are exchanged for long-term, low-interest reconstruction paper held by banks, insurers, postal savings institutions, pension funds, and corporate houses. Financial repression, inflation already suffered, and maturity extension carry part of the fiscal cost.</p><p>The conversion is not full repayment. It is an orderly recognition that the war debt cannot command immediate goods without destabilizing the peace.</p>"},
      {id:"development",title:"Imperial Development Account",html:"<p>The Bank of Japan ceases routine underwriting of ordinary deficits. A distinct development account combines postal savings, directed loans, imperial surpluses, and long bonds to finance approved infrastructure without unrestricted note creation.</p><p>This division prepares the later <a href='imperial-development-bank.html'>Imperial Development Bank</a> and makes credit allocation, rather than universal physical command, the principal Japanese planning instrument.</p>"},
      {id:"currencies",title:"Reorganization of imperial currencies",html:"<p>Old military currencies and occupation notes are canceled or converted on unequal schedules. Integral territories receive closer treatment than guardian republics, resource administrations, or newly associated states.</p><p>The settlement establishes the <a href='japanese-yen-area.html'>inner yen, development-currency, associated-currency, and clearing layers</a> that permit local notes to survive beneath Japanese financial supremacy.</p>"},
      {id:"legacy",title:"Political and institutional legacy",html:"<p>The reform stabilizes credit, makes civilian shipping and conversion financeable, and transforms emergency controls into a permanent bank-centered order. It also legitimizes blocked balances, controlled convertibility, and politically selected investment as ordinary peacetime tools.</p><p>Its success allows the <a href='first-greater-east-asia-reconstruction-plan.html'>First Greater East Asia Reconstruction Plan</a> to begin in 1949.</p>"}
    ],related:[{href:"japanese-yen-area.html",kicker:"Monetary successor",label:"Japanese Imperial Yen Area"},{href:"first-greater-east-asia-reconstruction-plan.html",kicker:"Immediate program",label:"First Greater East Asia Reconstruction Plan"},{href:"greater-east-asia-economic-board.html",kicker:"Planning institution",label:"Greater East Asia Economic Board"},{href:"mamoru-shigemitsu.html",kicker:"Political sponsor",label:"Mamoru Shigemitsu"}],
    facts:[["Year","1948"],["Formal name","Teikoku Kin’yū Seiri"],["Public name","New Yen Settlement"],["Primary aim","Disinflation and stable credit"],["Small balances","Preferentially protected"],["Large balances","Blocked or converted less favorably"],["War debt","Converted into long-term reconstruction paper"],["Successor program","First Greater East Asia Reconstruction Plan"]]
  }),

  "first-greater-east-asia-reconstruction-plan": japaneseEconomicArticle({
    title:"First Greater East Asia Reconstruction Plan",category:"Economic history",eyebrow:"Shigemitsu Construction Cabinet · 1949–1953",infoboxKicker:"First imperial peacetime plan",
    flag:{src:"assets/diagrams/japanese-development-plan-sequence.svg",alt:"Timeline of Japanese stabilization and development plans",caption:"The first plan turns the 1948 financial settlement into ships, fuel, power, housing, machinery, and technical institutions"},
    lead:"The First Greater East Asia Reconstruction Plan was the Shigemitsu government's principal economic program from 1949 into the early 1950s. It converted wartime capacity into merchant shipping and civilian industry, restored the logistics of the imperial market, and made the home islands the precision workshop of a deliberately unequal Asian production system.",
    canon:"The 1949 opening, Shigemitsu and Kishi roles, ten priority fields, broad 1949–1953 period, restoration effects, and factory-of-the-empire doctrine are established. Exact terminal year, appropriations, individual projects, and formal plan subtitle remain open.",
    sections:[
      {id:"cabinet",title:"The Construction Cabinet",html:"<p>Mamoru Shigemitsu supplies the diplomatic constitution of associated sovereignty while Nobusuke Kishi and the reform bureaucracy supply industrial machinery. Hoshino coordinates planning and Ichimada anchors monetary stabilization.</p><p>The government is civilian-faced rather than liberal: managed elections and regular ministries return while imperial direction, labor control, and strategic censorship persist.</p>"},
      {id:"priorities",title:"Ten priorities",html:"<p>The plan gives first claim on credit and shipping to merchant tonnage, oil and refining, port repair, coal and steel, electric power, railways, food and fertilizer, Japanese housing, machine tools, and technical education.</p><p>These fields are mutually reinforcing. Ships require steel and fuel; ports require power and rail; civilian conversion requires tools, housing, food, and trained labor.</p>"},
      {id:"shipping",title:"Restoring the maritime system",html:"<p>Merchant fleets, tanker routes, warehouses, insurance, repair yards, and port schedules reconnect the imperial economy. The Navy withdraws from ordinary commercial administration while retaining route protection and strategic reserve authority.</p><p>Commercial movement is the plan's first condition because resources in the East Indies or Indochina are useless to Osaka if tankers, bills, storage, and port cranes do not work.</p>"},
      {id:"conversion",title:"Factory conversion and home recovery",html:"<p>Aircraft, vehicle, ship, radio, and armament plants move toward trucks, civilian ships, machinery, household equipment, construction tools, and transport systems. Rationing ends gradually in Japan proper as food imports and consumer output recover.</p><p>Housing and ordinary goods are political necessities: victory must become materially visible rather than remain a claim written in treaties and military communiqués.</p>"},
      {id:"regions",title:"Regional industrial investment",html:"<p>Chōsen, Taiwan, and Manchukuo receive major investment because they are integral or chartered industrial extensions of Japan. China is rebuilt selectively but denied an autonomous strategic-industrial base.</p><p>Southeast Asian governments receive ports, extraction, refining, irrigation, and processing projects tied to concessions and Japanese markets.</p>"},
      {id:"administration",title:"Normalization without liberalization",html:"<p>Temporary occupation functions move to associated governments; Army and Navy economic offices enter the Economic Board's process; military taxes become tariffs, treaties, clearing accounts, and regular concessions.</p><p>Foreign diplomacy, Greater East Asian supervision, economic planning, defense policy, and corporate implementation are divided among permanent institutions so no wartime super-ministry becomes a second government.</p>"},
      {id:"doctrine",title:"The precision workshop doctrine",html:"<p>Internally, the home islands are described as the precision workshop of Greater East Asia. Japan provides leadership, finance, science, machinery, and defense; other regions contribute intermediate industry, resources, food, markets, administration, and manpower.</p><p>Public language promises that every region contributes according to its strength and shares in common prosperity. The difference between the two formulas defines the plan's politics.</p>"},
      {id:"legacy",title:"From reconstruction to permanent development",html:"<p>By the early 1950s civilian trade, the yen, ports, power, and industrial supply are sufficiently stable for Kishi to turn emergency reconstruction into a durable developmental regime.</p><p>The later <a href='greater-east-asia-prosperity-plan.html'>Prosperity Plan</a> expands household and associated-state benefits without abandoning the institutional architecture built here.</p>"}
    ],related:[{href:"imperial-financial-rectification.html",kicker:"Monetary foundation",label:"Imperial Financial Rectification"},{href:"greater-east-asia-economic-board.html",kicker:"Planning authority",label:"Greater East Asia Economic Board"},{href:"mamoru-shigemitsu.html",kicker:"Prime minister",label:"Mamoru Shigemitsu"},{href:"nobusuke-kishi.html",kicker:"Economic architect",label:"Nobusuke Kishi"},{href:"greater-east-asia-prosperity-plan.html",kicker:"Later program",label:"Greater East Asia Prosperity Plan"}],
    facts:[["Begun","1949"],["Working period","1949–1953"],["Prime minister","Mamoru Shigemitsu"],["Principal economic architect","Nobusuke Kishi"],["Priority sectors","Ten"],["First priority","Merchant shipping"],["Political form","Normalization without liberalization"],["Core doctrine","Home islands as precision workshop"]]
  }),

  "imperial-development-bank": japaneseEconomicArticle({
    title:"Imperial Development Bank",category:"Financial institutions",eyebrow:"Teikoku Kaihatsu Ginkō · postwar Japan",infoboxKicker:"Long-term imperial development lender",
    flag:{src:"assets/diagrams/japanese-imperial-economic-system.svg",alt:"Diagram of Japan's imperial economic system",caption:"The Bank converts strategic plans into long-term loans, guarantees, and project finance"},
    lead:"The Imperial Development Bank is Japan's principal long-term lender for strategic projects across the Co-Prosperity Sphere. It finances ports, power, steel, shipyards, railways, nuclear stations, mechanized agriculture, telecommunications, and technical education while normally leaving operation to governments, corporate houses, or specially chartered development companies.",
    canon:"The institution, Japanese rendering, relationship to the Economic Board, principal fields, lending model, public guarantees, and host-government borrowers are established. Its charter date, capitalization, headquarters building, branch network, and named governors remain open.",
    sections:[
      {id:"formation",title:"From development account to permanent bank",html:"<p>The 1948 settlement separates ordinary monetary stability from long-term imperial reconstruction. Postal savings, reconstruction bonds, directed bank finance, and state guarantees become a distinct development account.</p><p>The permanent Bank institutionalizes that account so infrastructure can receive maturities and political protection unavailable from ordinary commercial lending.</p>"},
      {id:"mandate",title:"Strategic lending mandate",html:"<p>The Bank funds projects whose value lies in transport, security, supply, technical capacity, or regional integration as well as immediate profit. It can accept long repayment, state guarantees, clearing balances, resource delivery, or concession revenue.</p><p>It does not normally finance ordinary shops or operate industry itself. Its role is to make a strategic project bankable.</p>"},
      {id:"fields",title:"Fields of finance",html:"<p>Typical sectors include ports, power plants, steel mills, shipyards, railways, mines, refineries, nuclear stations, irrigation, mechanized agriculture, telecommunications, schools, and research institutes.</p><p>The portfolio follows the Economic Board's plan rather than a universal development formula; regions receive different projects according to their assigned place in the imperial production ladder.</p>"},
      {id:"borrowers",title:"Borrowers and project companies",html:"<p>Borrowers include Japanese corporate houses, <a href='japanese-national-policy-corporations.html'>national-policy corporations</a>, associated governments, provincial authorities, Mantetsu subsidiaries, utilities, and mixed local development companies.</p><p>A project may be legally Mongolian, financed by the Bank, connected to a Japanese-controlled railway, equipped by Japanese manufacturers, and operated with local labor and a corporate technical mission.</p>"},
      {id:"conditions",title:"Conditions attached to credit",html:"<p>Loans may require Japanese machinery, approved contractors, clearing-yen settlement, tariff guarantees, technical schools, audited accounts, route access, or protection of a concession.</p><p>These conditions spread standards and ensure repayment. They also make the Bank an instrument through which nominally sovereign development reproduces Japanese control.</p>"},
      {id:"risk",title:"Public guarantees and political risk",html:"<p>Projects in frontier regions depend upon guarantees against war, currency change, expropriation, and interruption. Tokyo, the host government, a corporate house, and designated banks divide the risk by treaty and charter.</p><p>When a project fails, no participant wants to admit which guarantee has been called. Refinancing often postpones the political argument.</p>"},
      {id:"negotiation",title:"Development as bargaining",html:"<p>Associated governments bargain for local procurement, apprenticeships, management promotion, public access, environmental limits, and a share of revenue. The Bank can withhold finance; local authorities control land, police, labor, and permits.</p><p>Successful development therefore increases both Japanese leverage and the negotiating capacity of the borrower.</p>"},
      {id:"legacy",title:"Source of strength and bad debt",html:"<p>Patient finance permits infrastructure on a scale ordinary banks would not attempt and makes Japanese technical systems the default across the Sphere.</p><p>The same willingness to refinance strategic borrowers accumulates bad colonial loans and supports <a href='protected-national-enterprises-japan.html'>protected national enterprises</a> whose closure would expose political as well as financial losses.</p>"}
    ],related:[{href:"greater-east-asia-economic-board.html",kicker:"Planning authority",label:"Greater East Asia Economic Board"},{href:"japanese-national-policy-corporations.html",kicker:"Common borrower",label:"National-Policy Corporations"},{href:"japanese-yen-area.html",kicker:"Currency system",label:"Japanese Imperial Yen Area"},{href:"mantetsu.html",kicker:"Continental network",label:"Mantetsu"},{href:"protected-national-enterprises-japan.html",kicker:"Long-term weakness",label:"Protected National Enterprises"}],
    facts:[["Japanese name","Teikoku Kaihatsu Ginkō"],["Established","Post-1948; exact charter year open"],["Headquarters","Tokyo (exact site open)"],["Planning authority","Greater East Asia Economic Board"],["Principal function","Long-term strategic project finance"],["Typical borrowers","Governments, corporate houses, and policy corporations"],["Ordinary project operator","Borrower or charter company"],["Major long-term risk","Politically protected bad debt"]]
  }),

  "japanese-imperial-corporate-houses": japaneseEconomicArticle({
    title:"Imperial Corporate Houses of Japan",category:"Business history",eyebrow:"Zaibatsu after victory · 1947 onward",infoboxKicker:"Bank-centered corporate federations",
    flag:{src:"assets/diagrams/japanese-corporate-house-network.svg",alt:"Network diagram of an imperial Japanese corporate house",caption:"A mature house combines finance, trade, shipping, industry, research, and overseas concessions"},
    lead:"The imperial corporate houses are the victorious successors of Japan's zaibatsu. Mitsubishi, Mitsui, Sumitomo, Yasuda, Nissan, and Manchurian groups survive the war as bank-centered federations containing insurance, general trade, shipping, heavy and consumer industry, research, and overseas subsidiaries, all operating within state priorities.",
    canon:"Survival of the major houses, professional-management structure, broad sectoral tendencies, several-giants policy, founding-family prestige, and designated rising enterprises are established. Exact group boundaries, ownership percentages, boards, acquisitions, and postwar firm lists remain open.",
    sections:[
      {id:"survival",title:"No occupation dissolution",html:"<p>The holding companies, banks, shipyards, trading organizations, supplier networks, and colonial interests are not broken up by an occupation authority. Victory leaves the houses larger and more deeply embedded in the state than before the war.</p><p>Wartime law has already reduced the practical authority of outside shareholders and strengthened professional managers, designated banks, and ministry coordination.</p>"},
      {id:"structure",title:"The mature house",html:"<p>A major house commonly contains a holding organization, principal bank, insurer, <a href='sogo-shosha.html'>general trading company</a>, shipping interests, heavy industry, consumer firms, research laboratories, and overseas subsidiaries.</p><p>The founding family retains prestige, capital, appointments, and social standing; bankers, engineers, managers, and ministry liaison officers conduct much daily government.</p>"},
      {id:"mitsubishi",title:"Mitsubishi",html:"<p>Mitsubishi is associated especially with shipping, shipbuilding, naval aviation, heavy machinery, petroleum transport, and major southern concessions.</p><p>Its ability to connect a fleet, yard, bank, insurer, and resource subsidiary makes it suited to the maritime projects through which Japan holds the southern empire together.</p>"},
      {id:"mitsui",title:"Mitsui",html:"<p>Mitsui remains exceptionally broad in general trade, mining, chemicals, textiles, food procurement, banking, and continental distribution.</p><p>Its commercial information and contract network often gives it earlier knowledge of local prices, harvests, and political risk than formal ministries possess.</p>"},
      {id:"others",title:"Sumitomo, Yasuda, Nissan, and Manchurian groups",html:"<p>Sumitomo is strong in copper, metals, heavy electrical equipment, banking, chemicals, and machinery. Yasuda remains predominantly financial across banks, insurance, trusts, and colonial credit.</p><p><a href='nissan-motor-company.html'>Nissan</a> and Manchurian groups concentrate continental vehicles, railways, steel, coal, chemicals, and large-scale development under Army and reform-bureaucratic influence.</p>"},
      {id:"competition",title:"Several obedient giants",html:"<p>Tokyo prevents any one house from monopolizing an indispensable field. It does not seek a liberal market of atomized competitors; it preserves several capable groups that ministries can compare, reward, discipline, or play against one another.</p><p>Competition occurs within strategic ceilings on foreign ownership, technology, credit, and the closure of reserve capacity.</p>"},
      {id:"rising",title:"Designated rising enterprises",html:"<p>Promising specialists in electronics, vehicles, precision machinery, computing, components, and robotics can receive development loans, contracts, university access, tax relief, guaranteed purchases, and a trading-house partner. <a href='tokyo-tsushin-kogyo.html'>Tokyo Tsushin Kogyo</a> and <a href='honda-motor-company.html'>Honda</a> are leading examples.</p><p>Some are absorbed; others become independent industrial groups. The designation prevents the old houses from smothering every new technical field.</p>"},
      {id:"power",title:"Private power resting on public permission",html:"<p>Managers pursue profit and houses compete for projects, but strategic scale depends upon credit, exchange approval, routes, concessions, procurement, and official tolerance of losses.</p><p>The houses are neither ordinary private conglomerates nor state ministries. They are privileged institutions through which Tokyo makes imperial power commercially operative.</p>"}
    ],related:[{href:"japanese-imperial-economic-system.html",kicker:"Economic order",label:"Co-Prosperity Economic System"},{href:"sogo-shosha.html",kicker:"Commercial nervous system",label:"Sōgō Shōsha"},{href:"japanese-national-policy-corporations.html",kicker:"Chartered partners",label:"National-Policy Corporations"},{href:"tokyo-tsushin-kogyo.html",kicker:"Rising electronics firm",label:"Tokyo Tsushin Kogyo"},{href:"honda-motor-company.html",kicker:"Rising vehicle firm",label:"Honda Motor Company"},{href:"matsushita-electric-industrial.html",kicker:"Mass electrical firm",label:"Matsushita Electric Industrial"},{href:"greater-east-asia-economic-board.html",kicker:"Planning authority",label:"Greater East Asia Economic Board"},{href:"protected-national-enterprises-japan.html",kicker:"Accumulated weakness",label:"Protected National Enterprises"}],
    facts:[["Principal form","Bank-centered corporate federation"],["Leading houses","Mitsubishi, Mitsui, Sumitomo, Yasuda, Nissan, Manchurian groups"],["Founding families","Prestige, ownership, and board influence"],["Daily control","Managers, bankers, engineers, and ministry liaisons"],["Antitrust dissolution","Absent"],["Government preference","Several obedient giants"],["New-firm mechanism","Designated rising enterprise"],["Strategic dependence","Credit, routes, concessions, and procurement"]]
  }),

  "sogo-shosha": japaneseEconomicArticle({
    title:"Sōgō Shōsha",category:"Business institutions",eyebrow:"General trading companies · imperial commercial network",infoboxKicker:"Nervous system of Japanese trade",
    flag:{src:"assets/diagrams/japanese-corporate-house-network.svg",alt:"Network diagram of an imperial Japanese corporate house",caption:"General trading companies connect information, credit, shipping, insurance, storage, and corporate diplomacy"},
    lead:"The sōgō shōsha are Japan's general trading companies and the principal commercial nervous system of the Co-Prosperity Sphere. They combine market information, contracts, credit, foreign exchange, procurement, shipping, insurance, storage, project management, and political representation in a single institution able to assemble imperial transactions across several jurisdictions.",
    canon:"Their central imperial role, functional bundle, relationship to the corporate houses, transaction sequence, information advantage, and absence of a German-style central resource warehouse are established. Exact firms, tonnage, offices, and formal intelligence relationships remain open.",
    sections:[
      {id:"origins",title:"From general trade to imperial administration",html:"<p>Mitsui and Mitsubishi already possess broad international trading organizations before the divergence. Victory enlarges their task from buying and selling to coordinating entire chains of extraction, finance, transport, insurance, processing, and delivery.</p><p>Ministries cannot know every local harvest, freight rate, warehouse condition, contract dispute, and political relationship. The trading company becomes the institution that can.</p>"},
      {id:"functions",title:"A bundle of functions",html:"<p>A sōgō shōsha gathers information, negotiates contracts, arranges letters of credit, obtains exchange licenses, charters ships, purchases insurance, books storage, commissions machinery, and finds buyers.</p><p>Its breadth allows one office to see how a delay in a Burmese railway, Malayan port, Japanese refinery, or bank approval affects the whole transaction.</p>"},
      {id:"transaction",title:"An imperial petroleum transaction",html:"<p>When the Economic Board requires petroleum, a local government grants concessions; house banks finance drilling and refining; Japanese manufacturers supply equipment; the trading company charters tankers, insurance, and ports; the Navy protects routes; and the cargo reaches refiners or reserves.</p><p>The host receives taxes, local money, and <a href='greater-east-asia-clearing-yen.html'>clearing claims</a> redeemable through approved Japanese production and development.</p>"},
      {id:"information",title:"Commercial information and intelligence",html:"<p>Branch offices maintain reports on prices, harvests, labor, officials, shipping, credit, unrest, and competitors. This information is commercially valuable and routinely shared upward through banks, corporate headquarters, and public planning bodies.</p><p>The boundary between market intelligence, corporate diplomacy, and state security is deliberately porous without making every employee a formal intelligence officer.</p>"},
      {id:"diplomacy",title:"Corporate diplomacy",html:"<p>Trading-company representatives mediate among ministries, rulers, governors, port authorities, firms, and Japanese missions. A commercial concession may require the same patience and ceremonial judgment as a treaty.</p><p>Local elites often encounter Japanese power first through a resident manager who can deliver a ship, loan, engineer, scholarship, or Cabinet appointment route.</p>"},
      {id:"standards",title:"Spreading standards through commerce",html:"<p>Equipment contracts carry Japanese dimensions, parts, documentation, maintenance training, accounting forms, and later software. Insurance and finance reward compatible ports, warehouses, and procedures.</p><p>Technical integration thus spreads through ordinary procurement rather than a single decree applying one imperial code everywhere.</p>"},
      {id:"power",title:"Power without a central warehouse",html:"<p>Japan does not need one state warehouse to buy and resell all imperial resources. The trading houses collectively perform the warehouse, account, brokerage, shipping, insurance, and sales functions.</p><p>Their decentralization makes the system adaptable and opaque: public officials can deny direct management while every viable route still passes through privileged Japanese networks.</p>"},
      {id:"criticism",title:"Criticism and reform",html:"<p>Associated governments accuse the companies of tied contracts, transfer pricing, concealed commissions, political favoritism, and converting information superiority into permanent dependency.</p><p>Tokyo responds with audits, rival-house tenders, local-management quotas, and continuity rules. It rarely sacrifices the institution itself because no ministry can readily replace its integrated commercial knowledge.</p>"}
    ],related:[{href:"japanese-imperial-corporate-houses.html",kicker:"Parent networks",label:"Imperial Corporate Houses"},{href:"greater-east-asia-economic-board.html",kicker:"Strategic direction",label:"Greater East Asia Economic Board"},{href:"greater-east-asia-clearing-yen.html",kicker:"Settlement instrument",label:"Greater East Asia Clearing Yen"},{href:"japanese-imperial-economic-system.html",kicker:"Economic order",label:"Co-Prosperity Economic System"}],
    facts:[["Japanese term","Sōgō shōsha"],["English description","General trading company"],["Principal role","Imperial commercial coordination"],["Core functions","Information, contracts, credit, shipping, insurance, and storage"],["Typical affiliation","Major corporate house"],["State relationship","Privileged contractor and information partner"],["Central resource warehouse","None"],["Primary criticism","Opaque tied trade and information advantage"]]
  }),

  "japanese-national-policy-corporations": japaneseEconomicArticle({
    title:"National-Policy Corporations of Japan",category:"Business institutions",eyebrow:"Kokusaku kaisha · chartered imperial development",infoboxKicker:"Public-purpose corporate form",
    flag:{src:"assets/diagrams/japanese-imperial-economic-system.svg",alt:"Diagram of Japan's imperial economic system",caption:"National-policy corporations join state guarantees and monopolies to professional corporate operation"},
    lead:"Japanese national-policy corporations are specially created or privileged companies charged with strategic development while retaining corporate management and accounts. They receive guarantees, monopolies, concessions, directed loans, or shipping assignments and operate mines, railways, petroleum systems, irrigation, utilities, and development corridors that ordinary private capital would not undertake on equivalent terms.",
    canon:"The corporate form, public-guarantee/private-management character, overseas importance, principal sectoral examples, relationship to the Development Bank, and charter powers are established. Exact postwar corporation names, share structures, charters, and host-state ownership remain open.",
    sections:[
      {id:"definition",title:"A corporation ordered to exist",html:"<p>A national-policy corporation may have private shareholders, professional managers, profits, bonds, and ordinary contracts. Its strategic position exists because the state grants a charter, guarantee, monopoly, concession, or protected market.</p><p>It is not simply a ministry in company form, nor an ordinary firm that happened to win a contract.</p>"},
      {id:"precedent",title:"Prewar and wartime precedent",html:"<p>Japan enters the postwar era with experience in chartered railways, colonial development companies, power systems, and state-directed industrial corporations. Victory preserves both the legal form and the officials who understand it.</p><p>The model expands because it reconciles public direction with the managerial flexibility and outside capital of a company.</p>"},
      {id:"sectors",title:"Imperial sectors",html:"<p>Typical fields include Manchurian steel and railways, East Indian petroleum, Malayan rubber and tin, Indochinese rice and irrigation, Philippine shipping and development, Siberian mining, power, ports, and telecommunications.</p><p>Different states may own minority shares or appoint representatives without controlling the strategic capital plan.</p>"},
      {id:"finance",title:"Finance and guarantees",html:"<p>The <a href='imperial-development-bank.html'>Imperial Development Bank</a>, house banks, postal savings, government bonds, and host-state contributions provide capital. Public guarantees cover currency, minimum purchase, route access, political interruption, and debt service.</p><p>This structure keeps many contingent losses outside the ordinary ministry budget. The state nevertheless bears them when a protected project fails.</p>"},
      {id:"charter",title:"Charter powers",html:"<p>A charter may grant land, mining, customs, utility, police, railway, port, housing, labor-registration, or lower-court powers within a defined corridor. The scope varies by legal status and local bargaining strength.</p><p>These powers make the corporation part of government for residents even where sovereignty and citizenship remain formally local.</p>"},
      {id:"management",title:"Private management and public appointments",html:"<p>Professional managers conduct procurement, staffing, engineering, and daily accounts. Japanese ministries may hold special shares, nomination rights, audit powers, or vetoes over strategic changes.</p><p>Local directors and technicians can rise through the enterprise while final authority over ownership, routes, and technology remains protected.</p>"},
      {id:"host",title:"The corporate-host bargain",html:"<p>Host governments seek tax revenue, wages, training, infrastructure, public service, and a route into Japanese markets. Japan seeks stable concessions, strategic access, production, and compatible standards.</p><p>The bargain is durable where both receive visible benefits and unstable where company authority becomes naked extraction or a substitute for national administration.</p>"},
      {id:"legacy",title:"Development and charter rule",html:"<p>National-policy corporations build projects faster than weak governments could finance and give Tokyo a tool more flexible than annexation.</p><p>They also create company towns, inherited monopolies, and <a href='protected-national-enterprises-japan.html'>protected firms</a> whose public guarantees make closure politically explosive.</p>"}
    ],related:[{href:"imperial-development-bank.html",kicker:"Principal lender",label:"Imperial Development Bank"},{href:"japanese-imperial-corporate-houses.html",kicker:"Private partners",label:"Imperial Corporate Houses"},{href:"mantetsu.html",kicker:"Leading precedent",label:"Mantetsu"},{href:"chartered-restoration-territories.html",kicker:"Later Indian application",label:"Chartered Restoration Territories"},{href:"geacps.html",kicker:"International order",label:"Greater East Asia Co-Prosperity Sphere"}],
    facts:[["Japanese term","Kokusaku kaisha"],["Legal character","Specially created or privileged corporation"],["Management","Professional corporate administration"],["Public instruments","Guarantees, monopolies, concessions, and directed credit"],["Principal lender","Imperial Development Bank"],["Major theater","Associated and protected territories"],["Citizenship in company zones","Remains local"],["Central contradiction","Development through quasi-governmental private power"]]
  }),

  "greater-east-asia-clearing-yen": japaneseEconomicArticle({
    title:"Greater East Asia Clearing Yen",category:"Currencies and settlement",eyebrow:"Daitōa Seisan-en · noncash imperial accounting unit",infoboxKicker:"GEACPS clearing instrument",
    flag:{src:"assets/diagrams/japanese-layered-yen-area.svg",alt:"Diagram of the layered Japanese yen area",caption:"The Clearing Yen settles large imperial accounts without becoming a common circulating currency or gold claim"},
    lead:"The Greater East Asia Clearing Yen is the noncirculating accounting unit used for intergovernmental and major corporate settlement inside the Japanese economic sphere. Resource exporters receive claims redeemable through approved Japanese machinery, ships, industrial plants, arms, training, loans, and specified goods rather than an unrestricted right to domestic yen, gold, or rival-bloc currency.",
    canon:"The name, Japanese rendering, noncash character, approved-output redemption, wartime special-yen ancestry, imperial financing function, and distinction from both domestic yen and Gold Yen are established. Exact unit parity, account rules, interest, expiry, and arbitration procedure remain open.",
    sections:[
      {id:"origin",title:"From special yen to durable clearing",html:"<p>Wartime special-yen accounts allow Japan to acquire local purchasing power while restricting the holder's ability to redeem claims in Japan. Such blocked balances cannot support a stable postwar association if they remain openly fictitious.</p><p>The postwar system regularizes the account and provides enforceable, though controlled, redemption through Japanese output and development.</p>"},
      {id:"unit",title:"An account rather than a note",html:"<p>The Clearing Yen does not ordinarily circulate in wages, shops, or household savings. Governments, banks, trading houses, and large enterprises record balances through approved clearing institutions.</p><p>Local currency remains visible in daily life, insulating political symbolism from the less visible machinery of imperial settlement.</p>"},
      {id:"creation",title:"How balances are created",html:"<p>A territory earns claims by delivering oil, rice, rubber, tin, minerals, shipping services, military support, or other contracted output. Japanese exports, loans, and projects create offsetting obligations.</p><p>Valuation is negotiated through official exchange ratios, contract prices, freight, insurance, and quality schedules rather than a neutral world-market conversion.</p>"},
      {id:"redemption",title:"Approved redemption",html:"<p>Balances may purchase Japanese machinery, ships, industrial plants, military equipment, technical education, development loans, and specified consumer goods. Large projects can redeem several years of accumulated claims.</p><p>They do not create a general right to buy Tokyo land, transfer capital into Japanese banks, or demand gold and dollars.</p>"},
      {id:"finance",title:"Favorable imperial finance",html:"<p>Dependencies deliver physical resources in the present and accept a claim upon future Japanese production. This grants Tokyo long and inexpensive financing, especially when redemption waits upon factory capacity or plan approval.</p><p>Japan must still deliver enough useful output to prevent the unit from becoming a new name for wartime confiscation.</p>"},
      {id:"disputes",title:"Valuation and blocked-balance disputes",html:"<p>Recurring arguments concern whether raw materials are underpriced, machinery is overpriced, delivery is delayed, a project counts as redemption, or an exchange-rate change has silently transferred wealth.</p><p>Associated governments seek interest, transferable claims, delivery deadlines, and neutral audit. Tokyo resists rules that would turn the unit into unrestricted foreign exchange.</p>"},
      {id:"gold",title:"Distinction from the Gold Yen",html:"<p>The <a href='gold-yen.html'>Gold Yen</a> arises because fragmented Indian trade will not accept a claim redeemable chiefly through Japanese discretion. It is defined by fine gold and later becomes a wider external settlement instrument.</p><p>The domestic yen remains fiat, the Clearing Yen remains controlled imperial accounting, and the Gold Yen remains a separate hard claim.</p>"},
      {id:"power",title:"Sovereign currency, dependent settlement",html:"<p>A state may print its own money, regulate retail banks, and display monetary sovereignty while requiring Japanese clearing to obtain ships, machine tools, advanced weapons, or major credit.</p><p>The instrument therefore preserves flags and notes while concentrating the economic choices that determine industrial ascent.</p>"}
    ],related:[{href:"japanese-yen-area.html",kicker:"Monetary architecture",label:"Japanese Imperial Yen Area"},{href:"gold-yen.html",kicker:"External hard instrument",label:"Gold Yen"},{href:"sogo-shosha.html",kicker:"Transaction network",label:"Sōgō Shōsha"},{href:"greater-east-asia-economic-board.html",kicker:"Planning authority",label:"Greater East Asia Economic Board"},{href:"singapore.html",kicker:"Clearing center",label:"Singapore"}],
    facts:[["Japanese name","Daitōa Seisan-en"],["Form","Noncash accounting unit"],["Users","Governments, banks, and major corporations"],["Earned through","Contracted goods, resources, and services"],["Redeemed through","Approved Japanese output and development"],["Gold convertibility","None"],["Domestic circulation","Not ordinary"],["Separate external instrument","Gold Yen"]]
  }),

  "imperial-food-agency": japaneseEconomicArticle({
    title:"Imperial Food Agency",category:"Government agencies",eyebrow:"Food procurement, reserves, and relief · postwar Japan",infoboxKicker:"Imperial food-security authority",
    flag:{src:"assets/diagrams/japanese-imperial-economic-system.svg",alt:"Diagram of Japan's imperial economic system",caption:"Food is procured and reserved regionally within the same planned maritime network as fuel and industry"},
    lead:"The Imperial Food Agency is the Japanese authority coordinating grain contracts, regional reserves, shipping priorities, famine prevention, and emergency relief across the Co-Prosperity Sphere. Its early hierarchy protects the home islands and strategic installations first; postwar scandal and the developing Minimum Subsistence Principle force it to accept that associated territories cannot be stripped below survival merely to preserve Japanese consumption.",
    canon:"The Agency, regional procurement, early priority for Japan and strategic cities, outward transfer of shortage risk, and later relief-centered imperial responsibility are established. The location and date of the formative shortage scandal, formal Minimum Subsistence statute, reserve formulas, and agency leadership remain open.",
    sections:[
      {id:"war",title:"Wartime inheritance",html:"<p>Japan enters peace with controlled grain, rationing institutions, military shipping priorities, colonial procurement networks, and memories of requisition. Wartime authorities protected Japanese consumers and forces at severe cost to occupied populations.</p><p>Victory preserves the machinery but makes its unmodified use incompatible with the claim of common prosperity.</p>"},
      {id:"procurement",title:"Regional procurement",html:"<p>The Agency contracts rice and grain from Chōsen, Taiwan, Indochina, Thailand, accessible Burma, and selected Chinese provinces. It also coordinates fertilizer, seed, storage, crop reports, and emergency substitution.</p><p>Food is not all shipped to Tokyo. Regional reserves and treaty obligations are maintained because transport disruption can isolate several markets at once.</p>"},
      {id:"priority",title:"The early priority hierarchy",html:"<p>During the immediate postwar shortage, the home islands, armed forces, bases, settlers, and strategic industrial cities receive priority. Local populations bear more of a failed harvest when Tokyo refuses to reduce contracted shipments.</p><p>This reduces the probability of famine in Japan and transfers danger outward—the darkest everyday feature of the early economic settlement.</p>"},
      {id:"scandal",title:"The subsistence scandal",html:"<p>A late-1940s shortage in an Asian territory while deliveries continue to Japanese cities becomes the working origin of a major political scandal. Associated newspapers, students, clergy, younger officers, diplomats, and Diet members attack an empire that exports hunger while proclaiming shared prosperity.</p><p>The precise location, deaths, officials, and parliamentary sequence remain unsettled and should not be inferred as fixed.</p>"},
      {id:"principle",title:"Minimum Subsistence Principle",html:"<p>The developing principle holds that no member territory may be stripped below minimum subsistence to preserve nonessential consumption elsewhere. Japan and strategic bases may still receive marginal preference, but the Agency must defend reserve floors and record exceptions.</p><p>The principle is less than equality and more than charity: it turns famine prevention into a duty of imperial leadership.</p>"},
      {id:"relief",title:"Relief as imperial legitimacy",html:"<p>Navy transports, railways, aircraft, weather services, and corporate warehouses respond to typhoons, floods, crop failures, earthquakes, and port interruption. Relief becomes a central public image of a protective rather than predatory empire.</p><p>The assistance is real and politically selective. Reliable response can generate loyalty even where strategic sovereignty remains constrained.</p>"},
      {id:"information",title:"Food records and bargaining",html:"<p>Forecasts, reserve reports, shipping schedules, local prices, and nutritional estimates flow through ministries and trading houses. Local officials can manipulate figures to protect stocks; firms can exaggerate shortage to secure ships or prices.</p><p>The Agency therefore depends upon competing reports and field inspection, a practical limit on any claim of frictionless Tokyo control.</p>"},
      {id:"legacy",title:"The moral test of common prosperity",html:"<p>The Agency demonstrates the Japanese order's central political claim: hierarchy is justified when it provides predictable security and welfare. Failure cannot be dismissed as a local market event because Tokyo has claimed the authority to coordinate the whole system.</p><p>Food policy remains a recurring dispute between home-island preference, associated-state dignity, and the strategic needs of a maritime empire.</p>"}
    ],related:[{href:"japanese-imperial-economic-system.html",kicker:"Economic order",label:"Co-Prosperity Economic System"},{href:"greater-east-asia-economic-board.html",kicker:"Planning authority",label:"Greater East Asia Economic Board"},{href:"sogo-shosha.html",kicker:"Procurement network",label:"Sōgō Shōsha"},{href:"mamoru-shigemitsu.html",kicker:"Postwar political settlement",label:"Mamoru Shigemitsu"},{href:"geacps.html",kicker:"Imperial constitution",label:"Greater East Asia Co-Prosperity Sphere"}],
    facts:[["Established","Postwar consolidation; exact charter open"],["Principal role","Procurement, reserves, shipping, and relief"],["Major supply regions","Chōsen, Taiwan, Indochina, Thailand, Burma, and China"],["Early preference","Japan and strategic installations"],["Reform doctrine","Minimum Subsistence Principle (formal details open)"],["Operating model","Regional reserves and contracted movement"],["Relief carriers","Naval, civil, rail, air, and corporate systems"],["Core political test","Useful and protective hierarchy"]]
  }),

  "protected-national-enterprises-japan": japaneseEconomicArticle({
    title:"Protected National Enterprises in Japan",category:"Economic policy",eyebrow:"Strategic forbearance and soft budgets · 1970s onward",infoboxKicker:"Protected industrial capacity",
    flag:{src:"assets/diagrams/japanese-development-plan-sequence.svg",alt:"Timeline of Japanese stabilization and development plans",caption:"Rapid growth conceals the accumulating cost of protected firms, guaranteed loans, and politically preserved capacity"},
    lead:"Protected National Enterprises are strategically favored Japanese or imperial firms kept operating through refinancing, guarantees, procurement, merger, or reconstruction even when ordinary commercial returns no longer justify them. Officials reject the foreign label “zombie company,” arguing that shipyards, steel works, transport combines, and regional employers preserve capacities whose value cannot be measured by a single balance sheet.",
    canon:"The early soft-budget problem, protected strategic firms, official reconstruction language, leading causes, 1970s visibility, later competitive pressure, and refusal to call them zombies are established. The formal classification, number of enterprises, named restructurings, losses, and Nakasone-era program remain open.",
    sections:[
      {id:"origins",title:"The soft budget of directed credit",html:"<p>Each great house has a principal bank, the state directs strategic credit, and closures can damage suppliers, company towns, transport systems, military reserve capacity, or an associated government.</p><p>A lender therefore has reasons to extend another loan rather than recognize that the old loan and the public policy behind it have failed.</p>"},
      {id:"definition",title:"Strategically necessary reconstruction",html:"<p>Official language describes an unprofitable firm as a protected national enterprise undergoing reconstruction. Protection may include refinancing, guaranteed orders, debt conversion, tax relief, managed merger, new equipment, or a temporary monopoly.</p><p>The classification asserts that capacity, employment, security, and regional order possess value beyond current profit.</p>"},
      {id:"cases",title:"Typical protected capacity",html:"<p>A shipyard may remain open because the Navy wants reserve construction capacity. A Manchurian steel complex may support an entire industrial city. A textile or railway combine may be too entangled with banks and local government to close abruptly.</p><p>Not every protected firm is technologically obsolete; some are burdened by excess scale, inherited debt, political employment, or a mission that no longer pays.</p>"},
      {id:"banks",title:"Bank forbearance",html:"<p>House banks and public lenders roll debt, capitalize unpaid interest, or refinance through new development programs. Auditors can see weakness before it appears in ordinary insolvency statistics.</p><p>Admitting failure may implicate the bank, ministry, corporate house, host government, and Economic Board simultaneously, encouraging collective delay.</p>"},
      {id:"growth",title:"Why rapid growth conceals the problem",html:"<p>Expanding imperial demand, reconstruction, military procurement, and household consumption keep capacity busy through the 1950s and 1960s. New loans can be repaid from a growing market even when the original investment was inefficient.</p><p>By the 1970s the system looks extraordinarily strong while already carrying bad colonial loans and redundant protected plant.</p>"},
      {id:"pressure",title:"The mature pressures",html:"<p>Consumer demand slows, automation reduces employment needs, associated states demand local competitors, industries acquire excess capacity, and foreign détente exposes firms to American, German, British, and Latin competition.</p><p>The public must then choose whether strategic independence justifies permanent subsidy and whether closure would betray the corporate social contract.</p>"},
      {id:"reform",title:"Reconstruction, merger, and competitive procurement",html:"<p>Later governments favor audits, house-to-house competition, mergers, selective closure, export tests, competitive procurement, and separation of genuine reserve capacity from patronage. They do not dismantle developmental government.</p><p>Exact programs and major corporate cases remain open, particularly after the World Market Boom brings unfamiliar external competition.</p>"},
      {id:"meaning",title:"The price of refusing failure",html:"<p>Protection preserves skills, towns, supply chains, and strategic options that a short commercial test might destroy. It also diverts capital from rising enterprises and allows political relationships to masquerade as national necessity.</p><p>The issue is not whether Japan has markets or private firms. It is whether the state will permit strategically connected losses to become recognized failures.</p>"}
    ],related:[{href:"japanese-imperial-economic-system.html",kicker:"Economic order",label:"Co-Prosperity Economic System"},{href:"japanese-imperial-corporate-houses.html",kicker:"Corporate structure",label:"Imperial Corporate Houses"},{href:"imperial-development-bank.html",kicker:"Public lender",label:"Imperial Development Bank"},{href:"greater-east-asia-economic-board.html",kicker:"Planning authority",label:"Greater East Asia Economic Board"},{href:"world-market-boom.html",kicker:"External pressure",label:"World Market Boom"}],
    facts:[["Common official description","Protected National Enterprise"],["Foreign critical label","Zombie company"],["Visible problem","1970s onward"],["Principal mechanism","Bank and state forbearance"],["Typical sectors","Shipbuilding, steel, transport, colonial combines"],["Official response","Reconstruction, merger, procurement, or selective closure"],["Systemic cause","Strategic credit and interdependent guarantees"],["Exact firms and losses","Open"]]
  }),

  "greater-east-asia-economic-board": japaneseEconomicArticle({
    title:"Greater East Asia Economic Board",category:"Organizations",eyebrow:"Daitōa Keizai-in · strategic planning institution · from 1948",infoboxKicker:"Coordinator of the imperial economy",
    flag:{src:"assets/diagrams/japanese-imperial-economic-system.svg",alt:"Diagram of Japan's imperial economic system",caption:"The Board sets strategic direction while ministries, banks, houses, and associated governments implement projects"},
    lead:"The Greater East Asia Economic Board is the principal strategic planning institution of the Japanese imperial economy. It prepares multi-year priorities for shipping, food, petroleum, steel, power, education, industry, transport, and regional specialization without directly administering every enterprise.",
    canon:"The Board, 1948 consolidation, Tokyo location, Japanese rendering, remit, five- and ten-year planning, credit-and-shipping instruments, and relationship to ministries, banks, corporate houses, and associated governments are established. Formal membership, voting, statutory lineage, and internal bureaux remain open.",
    sections:[
      {id:"formation",title:"From wartime control to permanent planning",html:"<p>Wartime control associations, designated banks, military economic offices, and strengthened professional management survive victory. The 1948 <a href='imperial-financial-rectification.html'>financial settlement</a> converts these emergency arrangements into a permanent peace economy.</p><p>Kishi's Manchukuoan experience shapes the union of colonial development, private capital, finance, and state objectives.</p>"},
      {id:"position",title:"Position above ordinary sector administration",html:"<p>The Board addresses problems crossing ministerial boundaries: fuel affects shipping, steel, power, agriculture, housing, and defense simultaneously. It sets the hierarchy within which sector ministries issue rules and contracts.</p><p>It is not a universal super-ministry; foreign relations, defense, finance, and ordinary administration retain separate institutions.</p>"},
      {id:"plans",title:"Five- and ten-year plans",html:"<p>Plans cover tonnage, food reserves, energy, coal and steel, electricity, consumer production, skilled labor, schools, ports, railways, and regional industrial roles.</p><p>The <a href='first-greater-east-asia-reconstruction-plan.html'>First Reconstruction Plan</a> restores the system; the <a href='greater-east-asia-prosperity-plan.html'>Prosperity Plan</a> makes visible growth and associated-state capacity a test of legitimacy.</p>"},
      {id:"instruments",title:"Allocation without universal command",html:"<p>The Board determines which sectors receive cheap credit, ships, imported equipment, foreign exchange, concessions, guarantees, technical schools, procurement, and political protection.</p><p>A private project exists because every surrounding institution is instructed to make it possible, even where the Board never owns the factory.</p>"},
      {id:"finance",title:"Financial machinery",html:"<p>The <a href='japanese-ministry-of-finance.html'>Ministry of Finance</a> controls bank licenses, exchange, capital, bonds, and major foreign investment. The <a href='bank-of-japan.html'>Bank of Japan</a> manages the home yen and designated-bank liquidity. The <a href='imperial-development-bank.html'>Development Bank</a> supplies long strategic maturities.</p><p>The separation keeps ordinary currency stable while allowing approved infrastructure to receive directed finance.</p>"},
      {id:"corporate",title:"Corporate houses and policy companies",html:"<p><a href='japanese-imperial-corporate-houses.html'>Corporate houses</a>, <a href='sogo-shosha.html'>trading companies</a>, shipping lines, utilities, Mantetsu, and <a href='japanese-national-policy-corporations.html'>policy corporations</a> execute the plan.</p><p>The Board promotes several rival giants and protected rising enterprises rather than one monopoly.</p>"},
      {id:"hosts",title:"Negotiation with associated governments",html:"<p>Host governments bargain over taxation, wages, land, policing, local managers, public access, housing, and environmental burden. The Board trades finance and market access for compliance; local ministries can delay permits, labor, and routes.</p><p>Development creates stronger partners whose bargaining power grows with their technical capacity.</p>"},
      {id:"limits",title:"Information, favoritism, and soft budgets",html:"<p>The Board depends upon reports from ministries and firms that seek favorable targets, subsidies, or concealed failure. Trading houses can know local conditions better than planners; associated officials can manipulate land and production records.</p><p>Its ability to coordinate growth exceeds its ability to admit that a protected project should close, feeding the later <a href='protected-national-enterprises-japan.html'>soft-budget problem</a>.</p>"}
    ],related:[{href:"japanese-imperial-economic-system.html",kicker:"Economic constitution",label:"Co-Prosperity Economic System"},{href:"imperial-development-bank.html",kicker:"Development lender",label:"Imperial Development Bank"},{href:"greater-east-asia-prosperity-plan.html",kicker:"Major program",label:"Greater East Asia Prosperity Plan"},{href:"japanese-yen-area.html",kicker:"Monetary system",label:"Japanese Imperial Yen Area"},{href:"nobusuke-kishi.html",kicker:"Principal architect",label:"Nobusuke Kishi"}],
    facts:[["Established","1948 consolidation"],["Common Japanese rendering","Daitōa Keizai-in"],["Headquarters","Tokyo"],["Plan horizons","Five and ten years"],["Primary instruments","Credit, shipping, exchange, concessions, guarantees"],["Development lender","Imperial Development Bank"],["Implementation","Ministries, corporate houses, and associated governments"],["Membership and voting","Open"]]
  }),

  "japanese-yen-area": japaneseEconomicArticle({
    title:"Japanese Imperial Yen Area",category:"Economics",eyebrow:"Layered monetary architecture · from 1948",infoboxKicker:"Japanese-led currency and clearing system",
    flag:{src:"assets/diagrams/japanese-layered-yen-area.svg",alt:"Diagram of the layered Japanese yen area",caption:"Domestic yen, local development currencies, Clearing Yen, and Gold Yen remain legally distinct"},
    lead:"The Japanese imperial yen area is the layered monetary system connecting Japan, integral territories, protected states, principal associates, and external trading partners. It combines fiat domestic yen, local currencies under pegs or bands, a noncash Greater East Asia Clearing Yen, and a separate gold-denominated external settlement instrument.",
    canon:"The 1948 rectification, four-layer architecture, controlled convertibility, inner zone, local currencies, associated baht and peso autonomy, Clearing Yen, and separate Gold Yen are established. Exact exchange ratios beyond the working gold table, bank rules, and reform dates remain open.",
    sections:[
      {id:"rectification",title:"The 1948 monetary foundation",html:"<p>The <a href='imperial-financial-rectification.html'>Imperial Financial Rectification</a> protects small balances, converts large wartime holdings, exchanges debt for reconstruction paper, stabilizes credit, and reorganizes military and colonial notes.</p><p>It creates a stable fiat yen without promising general gold redemption.</p>"},
      {id:"inner",title:"Domestic and inner-imperial yen",html:"<p>The home islands, Chōsen, Taiwan, Karafuto, older Micronesia, and incorporated territories use domestic yen or territorial notes officially at par. They share Japanese nationality and the closest financial administration.</p><p>Parity does not permit unlimited capital movement. Exchange approval and bank rules protect Tokyo from uncontrolled regional transfers.</p>"},
      {id:"development",title:"Development-currency zone",html:"<p>Manchukuo, National China, Indochina, Malaya, and East Indian states retain local money managed against yen. Tokyo can alter rates to contain inflation, encourage exports, price machinery, or discipline an administration.</p><p>Visible national currencies coexist with Japanese influence over reserves, investment, and foreign trade.</p>"},
      {id:"associated",title:"Associated baht and peso systems",html:"<p>Thailand and the Philippines retain greater monetary authority. Their central banks hold substantial yen reserves; exchange bands, trade invoices, and development loans tie them to Japanese finance.</p><p>The arrangement makes their sovereignty more substantial than a puppet currency while still placing strategic development inside the yen system.</p>"},
      {id:"clearing",title:"Greater East Asia Clearing Yen",html:"<p>The <a href='greater-east-asia-clearing-yen.html'>Clearing Yen</a> settles intergovernmental and major corporate accounts without becoming a circulating note. Resource claims are redeemed through approved ships, machinery, plants, training, arms, loans, and goods.</p><p>It is not freely convertible into gold, dollars, or unrestricted home-island assets.</p>"},
      {id:"gold",title:"External Gold Yen",html:"<p>The <a href='gold-yen.html'>Gold Yen</a> begins in Indian trade where fiat and controlled clearing claims are insufficient. It is defined as a weight of fine gold and later broadens into a general external settlement instrument.</p><p>It remains legally separate from domestic yen and does not place Japan upon an ordinary gold standard.</p>"},
      {id:"institutions",title:"Banks and clearing centers",html:"<p>The <a href='japanese-ministry-of-finance.html'>Ministry of Finance</a>, <a href='bank-of-japan.html'>Bank of Japan</a>, Economic Board, designated banks, corporate houses, and central banks operate the system. Singapore becomes a principal clearing center while Tokyo retains final regulatory power.</p><p>Private contracts depend upon official exchange permission and access to approved settlement channels.</p>"},
      {id:"power",title:"Monetary sovereignty and industrial dependence",html:"<p>Associated states can issue notes, collect taxes, and govern retail banking while remaining unable to acquire advanced machinery, shipping, or strategic credit outside Japanese approval.</p><p>The architecture's political achievement is to preserve the appearance and some substance of national currency without surrendering control over industrial ascent.</p>"}
    ],related:[{href:"imperial-financial-rectification.html",kicker:"Foundational reform",label:"Imperial Financial Rectification"},{href:"greater-east-asia-clearing-yen.html",kicker:"Bloc accounting unit",label:"Greater East Asia Clearing Yen"},{href:"gold-yen.html",kicker:"External hard instrument",label:"Gold Yen"},{href:"greater-east-asia-economic-board.html",kicker:"Planning authority",label:"Greater East Asia Economic Board"},{href:"singapore.html",kicker:"Clearing center",label:"Singapore"}],
    facts:[["Foundational reform","Imperial Financial Rectification, 1948"],["Domestic currency","Fiat yen"],["Inner zone","Japan and integral imperial territories"],["Outer circulation","Local and associated-state currencies"],["Bloc settlement unit","Greater East Asia Clearing Yen"],["External hard instrument","Gold Yen"],["Common circulating Sphere currency","None"],["Principal clearing center","Singapore"]]
  }),

  "greater-east-asia-prosperity-plan": japaneseEconomicArticle({
    title:"Greater East Asia Prosperity Plan",category:"Economic history",eyebrow:"Ikeda-era imperial growth program · 1960–1965",infoboxKicker:"Prosperity as proof of imperial peace",
    flag:{src:"assets/diagrams/japanese-development-plan-sequence.svg",alt:"Timeline of Japanese stabilization and development plans",caption:"The Ikeda plan redirects inherited security-development machinery toward households and associated-state capacity"},
    lead:"The Greater East Asia Prosperity Plan was the 1960–1965 program through which Prime Minister Hayato Ikeda made visible household welfare, technical education, associated-state infrastructure, and upward movement through the imperial production ladder the principal test of Japanese leadership.",
    canon:"The period, Ikeda sponsorship, inherited Kishi machinery, major sectors, industrial-ladder doctrine, associated-state investments, Philippine showcase, technical education, and long-term contradictions are established. Appropriations, targets, project list, and statistical results remain open.",
    sections:[
      {id:"inheritance",title:"From control to growth",html:"<p>Kishi leaves disciplined credit, the Economic Board, strong corporate houses, a development bank, and a consolidated security system. Ikeda does not dismantle them; he gives them a public test—prosperity must prove that imperial peace is useful.</p><p>Mobilization instruments turn toward electricity, housing, schools, consumer output, and durable association.</p>"},
      {id:"home",title:"Household prosperity in Japan",html:"<p>Appliances, motorcycles, compact cars, reliable food, housing, education, and industrial employment translate strategic growth into ordinary legitimacy. Consumer industry receives more room inside an economy still dominated by planned credit.</p><p>The corporate social bargain expands with housing, benefits, apprenticeships, and stable technical careers.</p>"},
      {id:"program",title:"The 1960–1965 program",html:"<p>The Plan expands electrical generation, steel, shipping, machine tools, electronics, technical education, housing, nuclear power, consumer production, and associated-state infrastructure.</p><p>Projects are financed and operated through the Board, Development Bank, corporate houses, policy companies, and national governments rather than one imperial ministry.</p>"},
      {id:"ladder",title:"Movement up the industrial ladder",html:"<p>Chōsen expands steel and shipbuilding, Taiwan develops chemicals and electronics, and Manchukuo builds machinery. China receives rail-equipment, cement, agricultural-machinery, textile, and other ordinary factories. Malaya concentrates on refining, while the Philippines develops repair yards, fertilizer works, assembly plants, and merchant shipping.</p><p>Japan retains the highest-value design, finance, precision, computing, robotics, naval, aerospace, and nuclear fields.</p>"},
      {id:"philippines",title:"The Philippine showcase",html:"<p>The Philippines becomes the most politically valuable demonstration because it chooses association after defeating American tutelage. Projects include naval and merchant yards, computing, electrification, flood control, fertilizer, hydropower, processing, assembly, scholarships, hospitals, and universities.</p><p>Corruption and arrogance coexist with enough visible success to sustain the official contrast between American soldiers and Japanese ships, machines, and engineers.</p>"},
      {id:"education",title:"Technical education as integration",html:"<p>Scholarships and colleges train engineers, managers, technicians, physicians, and officers throughout the Sphere. Credentials bind graduates to Japanese standards and firms while supplying the manpower the home islands lack.</p><p>Every successful non-Japanese technical class also weakens the claim that strategic leadership must remain permanently Japanese.</p>"},
      {id:"automation",title:"Automation and higher-value leadership",html:"<p>As lower-value production moves outward, Japan must remain ahead through automation, microelectronics, robotics, advanced machinery, and nuclear power. The empire's development drives the home islands toward the next technical level.</p><p>This is not merely labor saving; it preserves hierarchical leadership in a system whose associated economies are becoming more capable.</p>"},
      {id:"legacy",title:"Growth without equality",html:"<p>By 1965 production chains are deeper, households richer, local technical classes larger, and association more credible. Japan has become a developmental hegemon rather than only a wartime occupier.</p><p>The plan also deepens corporate dependence and protects excess strategic capacity, contributing to later <a href='protected-national-enterprises-japan.html'>soft-budget enterprises</a>.</p>"}
    ],related:[{href:"first-greater-east-asia-reconstruction-plan.html",kicker:"Predecessor",label:"First Greater East Asia Reconstruction Plan"},{href:"greater-east-asia-economic-board.html",kicker:"Planning authority",label:"Greater East Asia Economic Board"},{href:"hayato-ikeda.html",kicker:"Prime minister",label:"Hayato Ikeda"},{href:"philippines.html",kicker:"Showcase associate",label:"Philippine Republic"},{href:"protected-national-enterprises-japan.html",kicker:"Long-term weakness",label:"Protected National Enterprises"}],
    facts:[["Period","1960–1965"],["Prime minister","Hayato Ikeda"],["Planning authority","Greater East Asia Economic Board"],["Core doctrine","Prosperity is the proof of imperial peace"],["Principal showcase","Philippine Republic"],["Economic model","Hierarchical industrial ladder"],["Social instrument","Technical education and firm-centered welfare"],["Long-term weakness","Protected capacity and corporate dependence"]]
  })
});

const addJapaneseEconomicRelated = (slug,items) => {
  const article = window.deepArticles[slug];
  if (!article) return;
  const existing = new Set((article.related || []).map(item => item.href));
  article.related = [...(article.related || []),...items.filter(item => !existing.has(item.href))];
};

